// Normalize Step 1 signals, apply decay weights, enforce URL + date rule
const cfg = $('Config & Guardrails (dry_run=true)').first().json;
const raw = $input.first().json;
let candidates = [];
try {
  const text = raw?.choices?.[0]?.message?.content || '[]';
  const match = text.match(/\[[\s\S]*\]/);
  candidates = match ? JSON.parse(match[0]) : [];
} catch {
  candidates = [];
}

const now = Date.now();
const scored = candidates
  .filter(c => c.company_name && c.domain && c.source_url && c.event_date)
  .map(c => {
    const ageDays = Math.max(0, Math.floor((now - new Date(c.event_date).getTime()) / 86400000));
    const decay = ageDays <= 30 ? 1.0 : ageDays <= 60 ? 0.5 : ageDays <= 90 ? 0.25 : 0;
    const baseWeight = Number(c.base_weight || 0.8);
    return {
      pod_id: cfg.pod_id,
      target_product: c.target_product || cfg.target_product,
      company_name: c.company_name,
      domain: String(c.domain).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0],
      signal_type: c.signal_type || 'new_facility',
      event_date: c.event_date,
      source_url: c.source_url,
      factual_summary: c.factual_summary || '',
      timing_score: Number((baseWeight * decay).toFixed(2)),
      dry_run: cfg.dry_run,
      require_approval: cfg.require_approval
    };
  })
  .filter(c => c.timing_score > 0)
  .slice(0, cfg.daily_cap || 20);

return scored.map(item => ({ json: item }));

// Filter strictly to VERIFIED emails; log collisions/quarantines cleanly
const input = $input.first().json;
const signal = $('Step 1b: Signal Decay & Dedupe').item.json;
const contacts = Array.isArray(input.contacts) ? input.contacts : (input.email ? [input] : []);

const verified = contacts.filter(c => c.email && String(c.email_status || 'VERIFIED').toUpperCase() === 'VERIFIED');
return verified.map(c => ({
  json: {
    ...signal,
    contact_name: c.name || c.full_name || 'Operations Leader',
    contact_title: c.title || 'Logistics Decision Maker',
    contact_email: c.email,
    contact_phone: c.phone || null,
    contact_linkedin: c.linkedin_url || null,
    email_status: 'VERIFIED'
  }
}));

