// Step 5b Deterministic Claims & Copy Linter
const prev = $('Step 3b: Verified Email Gate').item.json;
const claudeText = $input.first().json?.content?.[0]?.text || '{}';
let draft = { subject: 'dock capacity check', body: '', proof_point: prev.source_url };
try {
  const m = claudeText.match(/\{[\s\S]*\}/);
  if (m) draft = { ...draft, ...JSON.parse(m[0]) };
} catch {}

const words = String(draft.body || '').trim().split(/\s+/).filter(Boolean).length;
const hasBannedFiller = /(hope this finds you well|synergy|game-changer|revolutionize)/i.test(draft.body || '');
const linterPassed = words > 0 && words <= 105 && !hasBannedFiller;

return [{
  json: {
    ...prev,
    email_subject: draft.subject,
    email_body: draft.body,
    proof_point: draft.proof_point,
    word_count: words,
    linter_passed: linterPassed,
    approval_status: 'PENDING_REVIEW'
  }
}];
